      },
      {
        "statement": "The company handles full system replacement, preventive maintenance, and repairs for heating, cooling, and water equipment.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/about",
        "quote": "Our licensed and insured team works with furnaces, air conditioners, ductless systems, water heaters, water softeners, water purification systems, and indoor air quality solutions"
