    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.cornerstonecomfort.net/",
    "claims": [
      {
        "statement": "The company highlights over 500 five-star customer reviews across the Treasure Valley.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/about",
