  "licensing": {
    "claims": [
      {
        "statement": "Cornerstone Comfort holds Idaho contractor license #051546.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "Cornerstone Comfort is licensed and insured to perform heating, air conditioning, and water services in Idaho. ​License #051546"
      }
    ],
    "limitations": "Licensing evidence is based on public disclosures in the website footer; state licensing board databases were not independently queried."
  },
  "existingSoftware": [
    {
      "product": "Housecall Pro",
      "purpose": "Field service management and online scheduling",
      "evidence": {
        "statement": "The website references Housecall Pro's booking service domain within its page assets.",
        "label": "inference",
        "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
        "quote": null
      }
    },
    {
      "product": "Wix",
      "purpose": "Website hosting, content management, and native contact forms",
      "evidence": {
        "statement": "The website is built and served on the Wix platform, using Wix ThunderBolt runtime and Wix Form App widgets.",
        "label": "inference",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": null
      }
    },
    {
      "product": "Google Ads",
      "purpose": "Paid search advertising and conversion tracking",
      "evidence": {
        "statement": "The site loads a Google Ads conversion tracking tag (AW-11223296975).",
        "label": "inference",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": null
