      "purpose": "User behavior analytics and session tracking",
      "evidence": {
        "statement": "Microsoft Clarity analytics script is installed across web pages.",
        "label": "inference",
        "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The business actively pays for traffic via Google Ads and Meta Pixel to capture HVAC replacement and repair leads.",
      "label": "inference",
      "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
      "quote": null
    },
    {
      "statement": "Multiple independent form entry points exist on the site alongside Housecall Pro scheduling.",
      "label": "fact",
      "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
      "quote": "Get a Price Quote First name * Last name * Email * Phone * Select a Service * Choose an option Give us more details"
    },
    {
      "statement": "Customer inquiries and email mailto links are split between the rebrand domain and legacy domain.",
      "label": "inference",
      "sourceUrl": "https://www.cornerstonecomfort.net/about",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Potential lead response lag from unintegrated Wix quote forms and instant estimate inquiries before entering Housecall Pro.",
      "label": "hypothesis",
      "basis": "The website employs standalone Wix forms across multiple pages alongside Housecall Pro booking; whether form submissions automatically trigger immediate dispatch tickets or require manual copy-paste is unverified."
    },
    {
      "problem": "Disjointed executive tracking of paid ad spend against booked field-service revenue in Housecall Pro.",
      "label": "hypothesis",
      "basis": "The company actively runs Google Ads and Meta campaigns, but reporting between ad clicks, quote requests, and completed jobs in field-service software typically requires custom attribution pipeline setup."
    },
    {
      "problem": "Risk of dropped customer inquiries during seasonal peaks due to split email addresses across legacy domain (yzzysservice.com) and current domain (cornerstonecomfort.net).",
      "label": "hypothesis",
      "basis": "Mailto links on multiple pages direct to [redacted] while display footers show [redacted], creating potential inbox fragmentation."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Housecall Pro native online booking widget",
      "addresses": "Allows customers to directly book appointments into the field-service calendar.",
      "alreadyOwned": true
    },
    {
      "solution": "Zapier or Make webhook integration between Wix Forms and Housecall Pro",
      "addresses": "Automatically creates new customer records and job requests in Housecall Pro whenever a Wix web form is submitted.",
      "alreadyOwned": false
    },
    {
      "solution": "Google Ads and Google Tag Manager conversion integration",
      "addresses": "Tracks web form submissions back to paid search keywords.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [
    {
      "name": "Lead-to-job pipeline",
      "kind": "catalog",
      "description": "Every lead from every source lands in your field-service software within two minutes, gets an instant reply, and nobody forgets to call back.",
      "problem": "Potential lead response lag from unintegrated Wix quote forms and instant estimate inquiries before entering Housecall Pro.",
      "whyNotExistingSoftware": "While Housecall Pro provides online booking, leads generated through Wix contact forms, instant estimate requests, and phone callbacks often sit unparsed in email notifications without custom webhook routing and immediate multi-channel response."
    },
    {
      "name": "Revenue Leak Check",
      "kind": "catalog",
      "description": "In one week, see how many calls, leads and quotes slip through, and what they are worth to you. The $500 fee is credited in full to any fix you order within 30 days.",
      "problem": "Uncertainty regarding how many web quote submissions or ad clicks fail to convert into scheduled Housecall Pro dispatches.",
      "whyNotExistingSoftware": "Housecall Pro reports operational jobs while Google Ads reports clicks, but neither audits the end-to-end drop-off rate of inbound web inquiries."
    },
    {
      "name": "Owner's Monday numbers",
      "kind": "catalog",
      "description": "One page every Monday: booked revenue, close rate, average ticket, cost per booked job by lead source and money owed, from your field-service software, QuickBooks and ad accounts.",
      "problem": "Disjointed executive tracking of paid ad spend against booked field-service revenue in Housecall Pro.",
      "whyNotExistingSoftware": "Housecall Pro and ad platforms do not natively combine ad spend, close rates, and average job ticket into a single weekly scorecard without manual compilation."
    }
  ],
  "feasibility": {
    "rating": "high",
    "explanation": "Cornerstone Comfort operates on standard modern platforms (Wix, Google Ads, Housecall Pro). Housecall Pro supports standard API and webhook connectors, making automated lead intake and data extraction highly feasible."
  },
  "aiDelivery": {
    "rating": "partly",
    "explanation": "AI can parse unstructured job details from inbound web messages and draft instant follow-ups, but job dispatching, physical evaluations, and pricing confirmation require deterministic scheduling rules and human oversight."
  },
  "humanReview": [
    "Dispatch manager review before assigning technicians to scheduled service calls.",
    "On-site diagnostic validation and formal estimate sign-off by licensed technicians prior to installation.",
    "Owner approval of weekly financial attribution reports and ad spend reconciliations."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Faulty lead routing or automated scheduling could result in dispatch conflicts or missed emergency calls during high-demand weather extremes."
    },
    {
      "type": "compliance",
      "description": "Automated SMS responses must strictly adhere to TCPA opt-in requirements and Honor the company's stated opt-out policies."
    },
    {
      "type": "security",
      "description": "Inbound homeowner service addresses, phone numbers, and equipment details must be securely transmitted between Wix and Housecall Pro with encryption in transit."
    }
  ],
  "commercial": {
    "supportable": true,
    "value": "$2,450 to $5,499 per recovered replacement job, or $139 per recovered maintenance tune-up (illustrative)",
    "implementationCost": "$500 fixed price for Revenue Leak Check, or $1,800 setup plus $149/month for Lead-to-job pipeline",
    "assumptions": [
      "Illustrative pricing basis: The company publishes standard promotional prices including $2,450 for a hot water heater installation, $5,499 for a tankless water heater installation, and $139 for one-time HVAC maintenance.",
      "Assumption: If lead capture automation prevents even one high-ticket water heater or replacement HVAC inquiry from falling through the cracks or booking with a competitor each month, illustrative gross revenue saved is $2,450 to $5,499.",
      "Assumption: Converting 5 missed web inquiries into maintenance visits per month yields $695 in immediate diagnostic revenue and long-term Comfort Club membership opportunities ($200 to $500/year)."
    ]
  },
