    "sourcesUsed": [
      {
        "url": "https://www.cornerstonecomfort.net/",
        "usedFor": "Verified business identity, founders, location, services, licensing declaration, and advertising tracking tags."
      },
      {
        "url": "https://www.cornerstonecomfort.net/about",
