      },
      {
        "url": "https://www.cornerstonecomfort.net/financing",
        "usedFor": "Lender partnerships (Wells Fargo) and financing offerings."
      }
    ],
    "limitations": [
      "Total employee headcount is not explicitly stated on the public website; multi-technician operations are inferred from 2-man installation notices and regional coverage, but exact staff size cannot be confirmed from public pages.",
      "Internal integration status between Wix forms, email systems, and Housecall Pro dispatch cannot be directly inspected without backend access.",
      "Licensing status was confirmed via company site declarations and was not independently validated through state regulatory lookup."
    ]
  },
  "qualification": {
    "category": "pursue later",
    "rationale": "Cornerstone Comfort is an owner-led residential HVAC and water contractor founded by [redacted], actively paying for digital leads via Google Ads and Meta Pixel, and utilizing Housecall Pro. While it represents a plausible operational fit, exact staff size (segment requires ~10 to 75 staff) is not published on the site, and potential lead latency or manual double-entry between Wix forms and Housecall Pro remains an unconfirmed hypothesis rather than an established fact on the public website. Outreach is warranted to explore internal pipeline bottlenecks."
  }
